package ro.leo.visual;
import java.io.*;import java.util.*;import java.util.zip.*;import java.nio.file.*;
final class PocketZip {
 static final long MAX=100L*1024*1024;static final int ENTRIES=2000;
 static String safe(String name)throws IOException{if(name.isEmpty()||name.length()>1024||name.startsWith("/")||name.contains("\\")||name.indexOf(':')>=0||name.indexOf('\0')>=0)throw new IOException("Unsafe ZIP path");for(String part:name.split("/"))if(part.equals("..")||part.equals("."))throw new IOException("Unsafe ZIP path");return name;}
 static List<String> list(File zip)throws IOException{ArrayList<String> names=new ArrayList<>();long bytes=0;try(ZipFile z=new ZipFile(zip)){Enumeration<? extends ZipEntry> e=z.entries();HashSet<String> seen=new HashSet<>();while(e.hasMoreElements()){ZipEntry f=e.nextElement();String name=safe(f.getName());if(!seen.add(name)||names.size()>=ENTRIES)throw new IOException("Duplicate or too many entries");if(f.getSize()>32L*1024*1024||f.getSize()<0)throw new IOException("Invalid entry size");bytes+=f.getSize();if(bytes>MAX)throw new IOException("ZIP expansion limit: 100 MiB");names.add(name+" · "+f.getSize()+" B");}}return names;}
 static File extract(File zip,File output)throws IOException{list(zip);if(output.exists()||!output.mkdir())throw new IOException("Output must be a new folder");boolean success=false;long total=0;try(ZipFile z=new ZipFile(zip)){Enumeration<? extends ZipEntry> entries=z.entries();while(entries.hasMoreElements()){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();ZipEntry e=entries.nextElement();File target=new File(output,safe(e.getName()));if(!FileTransfers.inside(output,target))throw new IOException("ZIP escapes output");if(e.isDirectory()){if(!target.isDirectory()&&!target.mkdirs())throw new IOException("Cannot create folder");continue;}File parent=target.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("Cannot create folder");if(!target.createNewFile())throw new IOException("Duplicate output");long size=0;CRC32 crc=new CRC32();try(InputStream in=z.getInputStream(e);FileOutputStream out=new FileOutputStream(target)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();size+=n;total+=n;if(size>32L*1024*1024||total>MAX)throw new IOException("ZIP expansion limit");crc.update(b,0,n);out.write(b,0,n);}out.getFD().sync();}if(size!=e.getSize()||crc.getValue()!=e.getCrc())throw new IOException("ZIP CRC/size mismatch");}success=true;return output;}finally{if(!success)cleanup(output,output);}}
 private static void cleanup(File root,File f)throws IOException{if(!FileTransfers.inside(root,f)||Files.isSymbolicLink(f.toPath()))throw new IOException("Unsafe cleanup path");File[] children=f.listFiles();if(children!=null)for(File child:children)cleanup(root,child);if(!f.delete()&&f.exists())throw new IOException("Incomplete output cleanup");}
 static void create(File source,File output)throws IOException{if(!source.isFile()||Files.isSymbolicLink(source.toPath())||source.length()>32L*1024*1024||output.exists())throw new IOException("Invalid source/output");File temp=File.createTempFile(".leo-zip-",".part",output.getParentFile());boolean success=false;try{try(FileOutputStream raw=new FileOutputStream(temp);ZipOutputStream zip=new ZipOutputStream(raw);InputStream in=new FileInputStream(source)){zip.putNextEntry(new ZipEntry(safe(source.getName())));byte[] b=new byte[65536];long bytes=0;int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();bytes+=n;if(bytes>32L*1024*1024)throw new IOException("Source grew beyond entry limit");zip.write(b,0,n);}zip.closeEntry();zip.finish();raw.getFD().sync();}list(temp);Files.move(temp.toPath(),output.toPath());success=true;}finally{if(!success)temp.delete();}}
}
